local RobloxCSharp = _G.RobloxCSharp or {}
-- Generated by CSharp.lua Compiler
local System = _G.System or require(game:GetService("ReplicatedStorage"):WaitForChild("CoreSystem"))
local Roblox
System.import(function (out)
  Roblox = out.Roblox
end)
System.namespace("RobloxCSharp.Entities", function (namespace)
  -- Простой базовый класс Героя
  namespace.class("Hero", function (namespace)
    local Initialize, CreateOverheadGui, UseAbility, __ctor__
    __ctor__ = function (this, player, character, humanoid)
      this.Player = player
      this.Character = character
      this.Humanoid = humanoid
      local default
      if player ~= nil then
        default = player.Name
      else
        default = "Hero"
      end
      this.Name = default
    end
    Initialize = function (this)
      -- Устанавливаем базовое здоровье и скорость
      if this.Humanoid ~= nil then
        this.Humanoid.MaxHealth = this.MaxHealth
        this.Humanoid.Health = this.Health
        this.Humanoid.WalkSpeed = 16
      end

      -- Создаем простой бейдж с именем над головой
      CreateOverheadGui(this)

      System.Console.WriteLine("[Герой] Создан базовый герой: " .. System.toString(this.Name))
    end
    CreateOverheadGui = function (this)
      local head = System.cast(Roblox.BasePart, this.Character:FindFirstChild("Head", false))
      if head == nil then
        return
      end

      -- Удаляем старый GUI если есть
      local oldGui = head:FindFirstChild("HeroOverhead", false)
      if oldGui ~= nil then
        oldGui:Destroy()
      end

      -- Создаем новый BillboardGui
      local billboard = Instance.new("BillboardGui")
      billboard.Name = "HeroOverhead"
      billboard.Adornee = head
      billboard.Size = UDim2.new(0, 150, 0, 40)
      billboard.StudsOffset = Vector3.new(0, 2.5, 0)
      billboard.AlwaysOnTop = true
      billboard.Parent = head

      -- Текстовая плашка с именем и классом
      local nameLabel = Instance.new("TextLabel")
      nameLabel.Size = UDim2.new(1, 0, 1, 0)
      nameLabel.BackgroundTransparency = 1
      nameLabel.Text = System.toString(this.Name) .. " [Герой]"
      nameLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
      nameLabel.TextScaled = true
      nameLabel.Font = 19 --[[Font.GothamBold]]
      nameLabel.Parent = billboard
    end
    UseAbility = function (this)
      System.Console.WriteLine("[Герой] Использована базовая способность героя " .. System.toString(this.Name))
    end
    return {
      Health = 100,
      MaxHealth = 100,
      Initialize = Initialize,
      CreateOverheadGui = CreateOverheadGui,
      UseAbility = UseAbility,
      __ctor__ = __ctor__
    }
  end)
end)

